using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app-settings",
    Description = "Returns the current application configuration")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResourceMethod]
    public string GetConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool(Name = "echo"), Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool(Name = "get_server_time"), Description("Returns the current server time in UTC")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("O");
    }
}

